def is_contained(path: str) -> bool:
    """True when path, read relative to a directory, stays inside that directory: no absolute start and no climb above the start."""
    ex is_contained("a.txt") == True
    ex is_contained("sub/../a.txt") == True
    ex is_contained("../x") == False
    ex is_contained("sub/../../x") == False
    ex is_contained("/etc/passwd") == False
    if path.startswith("/"):
        return False
    depth = 0
    for seg in path.split("/"):
        if seg == "" or seg == ".":
            continue
        if seg == "..":
            depth -= 1
            if depth < 0:
                return False
        else:
            depth += 1
    return True

def read_public(path: str) -> str uses fs:
    """Text of the file at path inside the directory notes, or an empty string if the path leaves notes or the file cannot be read."""
    pre path.byte_len() >= 0
    post is_contained(path) or out == ""
    if not is_contained(path):
        return ""
    with fs = fs.sub("notes"):
        text = fs.read_text(path) else ""
        return text
